recipes.code:
{
  "inputs": [
    {
      "id": "foura-api-key",
      "type": "promptString",
      "description": "Your FourA API key (pk_live_...), managed at https://foura.ai/dashboard/#api-keys",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@fouradata/mcp@0.5.0"
      ],
      "env": {
        "FOURA_API_KEY": "${input:foura-api-key}"
      }
    }
  }
}
